export type InitialMaintenanceCatalog = {
    readonly parameters: readonly NumericParameter[];
    readonly items: readonly CostItem[];
    readonly requirements: readonly CostRequirement[];
};

export function createAdoptedMaintenanceCatalog(
    scenarioId: string,
    profileId: InitialProfileId,
    adoption: HistoricalMaintenanceAdoption
): InitialMaintenanceCatalog {
    const { reason } = adoption;

    const parameters: readonly NumericParameter[] = INITIAL_PROFILE_PARAMETERS[profileId];

    const items: readonly CostItem[] = INITIAL_COST_ITEMS.map(item => ({
        ...item,
        enabled: true,
        provenance: {
            kind: 'estimate',
            source: `RCF.md §6.2; profileId=${profileId}; reason=${reason}; hipótese histórica adotada`,
            date: null,
            competence: null,
            scope: { kind: 'scenario', scenarioId },
            reliability: 'conditional'
        }
    }));

    const requirements: readonly CostRequirement[] = INITIAL_COST_REQUIREMENTS.map(req => {
        const costItemIds = items
            .filter(item => item.enabled)
            .map(item => item.id) as [
            string,
            ...string[]
        ];
        return {
            ...req,
            status: 'applicable',
            costItemIds,
            provenance: {
                kind: 'estimate',
                source: `RCF.md §6.2; profileId=${profileId}; reason=${reason}; hipótese histórica adotada`,
                date: null,
                competence: null,
                scope: { kind: 'scenario', scenarioId },
                reliability: 'conditional'
            }
        };
    });

    return Object.freeze({
        parameters: Object.freeze(parameters),
        items: Object.freeze(items),
        requirements: Object.freeze(requirements)
    });
}

export { InitialMaintenanceCatalog };

